## 2. Pure‑C# version (for a compiled executable)

If you prefer a compiled binary that can be launched as a background service, the following minimal C# console program does essentially the same thing.  
It uses the **Win32 `RegNotifyChangeInformation`** WinAPI via P/Invoke, and writes to `C:\Windows\Logs\UserPrefChanges.txt`.

```csharp
// File: RegistryPrefWatcher.cs
// .NET 6+ (or .NET Framework 4.x) – compile with:  csc /out:RegistryPrefWatcher.exe RegistryPrefWatcher.cs

using System;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Win32;

class Program
{
    // ---------- Win32 structures ----------
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct REG_VALUE_INFORMATION
    {
        public uint DataType;
        public string ValueName;
        public IntPtr Data;            // Pointer to binary data (caller allocates)
        public uint DataSize;
    }

    [Flags]
    enum RegNotifyChangeFilter
    {
        Name               = 0x01,
        Attributes         = 0x02,
        RegistryValue      = 0x04,
        All                = Name | Attributes | RegistryValue
    }

    // ---------- Win32 imports ----------
    const uint ERROR_SUCCESS = 0;
    const uint ERROR_IO_PENDING = 997;
    const uint REG_NONE = 0;
    const uint REG_SZ = 1;
    const uint REG_DWORD = 4;

    [DllImport("advapi32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    static extern uint RegNotifyChangeKeyValue(
        RegistryKey hKey,
        bool bWatchDereg,
        RegNotifyChangeFilter dwNotifyFilter,
        IntPtr hEvent,
        bool fAsynchronous);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr CreateEvent(
        IntPtr lpEventAttributes,
        bool bManualReset,
        bool bInitialState,
        string lpName);

    [DllImport("kernel32.dll")]
    static extern bool SetEvent(IntPtr hEvent);

    [DllImport("kernel32.dll")]
    static extern bool WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);

    // ---------- Constants ----------
    static readonly string LogPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "Logs", "UserPrefChanges.txt");

    // ---------- Entry ----------
    static void Main()
    {
        // ----------------------------------------------------
        // Ensure log directory/file exists
        // ----------------------------------------------------
        var logDir = Path.GetDirectoryName(LogPath);
        if (!Directory.Exists(logDir))
            Directory.CreateDirectory(logDir);
        File.AppendAllText(LogPath, $"--- Registry monitor started at {DateTime.Now:u} ---\n");

        // ----------------------------------------------------
        // Keys we care about (HKCU equivalents)
        // ----------------------------------------------------
        string[] watchKeys = new[]
        {
            @"Software",
            @"Control Panel",
            @"Environment",
            @"Console",
            @"Keyboard Layout",
            @"Network",
            @"Desktop"
        };

        // ----------------------------------------------------
        // Create a named event that RegNotifyChangeKeyValue will signal
        // ----------------------------------------------------
        IntPtr hEvent = CreateEvent(IntPtr.Zero, false, false, "Global\\RegPrefWatcherEvent");
        if (hEvent == IntPtr.Zero)
            throw new Win32Exception(Marshal.GetLastWin32Error());

        foreach (var sub in watchKeys)
        {
            using var hKey = Registry.CurrentUser.OpenSubKey(sub, writable: true);
            if (hKey == null)
            {
                Log($"Key HKCU:\\{sub} does not exist – skipping.");
                continue;
            }

            // The API will block until a change occurs (unless fAsynchronous==true)
            uint result = RegNotifyChangeKeyValue(
                hKey.Handle,
                bWatchDereg: false,
                RegNotifyChangeFilter.All,
                hEvent,
                fAsynchronous: false);

            if (result != ERROR_SUCCESS && result != ERROR_IO_PENDING)
                Log($"RegNotifyChangeKeyValue failed for HKCU:\\{sub} – Win32 err {result}");
            else
                Log($"listening for changes under HKCU:\\{sub}");
        }

        // ----------------------------------------------------
        // Wait forever – every Wait returns we can optionally reset the event
        // ----------------------------------------------------
        while (true)
        {
            WaitForSingleObject(hEvent, 0xFFFFFFFF);
            SetEvent(hEvent); // reset for next round

            // *** In a production tool you would retrieve the changed value here,
            //     e.g. via a second call to RegQueryValueEx on the offending path.
            Log(">>> Registry change detected – log rotated at {0:u}", DateTime.Now);
        }
    }

    // Simple timestamped append helper (UTF‑8)
    static void Log(string fmt, params object[] args)
    {
        var line = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff}] {string.Format(fmt, args)}\n";
        File.AppendAllText(LogPath, line);
    }
}
